inline GUnzipStream::EStatus GUnzipStream::Read(const void **outputBuffer, int *outputBufferLength)
{
	int status = nzbget_rs_gunzip_read(
		static_cast<RsGUnzipStream*>(m_rsStream),
		outputBuffer,
		outputBufferLength);
	if (status == 1)
	{
		return zlFinished;
	}
	if (status == 2)
	{
		return zlOK;
	}
	return zlError;
}
